// src/App.js
import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";

import './App.css';
import Navbar from "./components/Navbar";
import HomePage from "./components/HomePage";
import SignIn from "./components/SignIn";
import SignUp from "./components/SignUp";
import Dashboard from "./components/Dashboard";
import ProhibitedAreaPage from "./components/ProhibitedAreaPage";
import StrictlyProhibitedAreaPage from "./components/StrictlyProhibitedAreaPage";

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);

  // Function to simulate signing in or signing up.
  const handleAuth = (userData) => {
    setIsAuthenticated(true);
    setUser(userData);
  };

  // Function to handle user logout.
  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(null);
  };

  return (
    <Router>
      {/* Pass onLogout to Navbar for the dropdown logout button */}
      <Navbar isAuthenticated={isAuthenticated} user={user} onLogout={handleLogout} />
      <Routes>
        <Route path="/" element={<HomePage isAuthenticated={isAuthenticated} />} />

        <Route 
          path="/signin" 
          element={
            isAuthenticated ? (
              <Navigate to="/dashboard" />
            ) : (
              <SignIn onAuth={handleAuth} />
            )
          }
        />

        <Route 
          path="/signup" 
          element={
            isAuthenticated ? (
              <Navigate to="/dashboard" />
            ) : (
              <SignUp onAuth={handleAuth} />
            )
          }
        />

        <Route 
          path="/dashboard" 
          element={
            isAuthenticated ? (
              <Dashboard user={user} />
            ) : (
              <Navigate to="/signin" />
            )
          }
        />

      </Routes>
    </Router>
  );
}

export default App;
